const unrecordedCardSales = `-- name: UnrecordedCardSales :many
SELECT l.id, l.kind,
  (l.principal_delta + CASE WHEN l.kind='open' THEN COALESCE((SELECT sum(ci.unit_price * ci.paid_count_opened) FROM card_items ci WHERE ci.card_id=l.card_id),0) ELSE 0 END)::text AS amount
FROM card_ledger l
WHERE l.store_id=$1 AND l.business_date=$2
  AND l.kind IN ('open','recharge','upgrade')
  AND (l.principal_delta + CASE WHEN l.kind='open' THEN COALESCE((SELECT sum(ci.unit_price * ci.paid_count_opened) FROM card_items ci WHERE ci.card_id=l.card_id),0) ELSE 0 END) > 0
  AND NOT EXISTS (SELECT 1 FROM sale_payments sp WHERE sp.tenant_id=l.tenant_id AND sp.card_ledger_id=l.id)
ORDER BY l.id
`

type UnrecordedCardSalesParams struct {
	StoreID uuid.UUID
	Day     pgtype.Date
}

type UnrecordedCardSalesRow struct {
	ID     uuid.UUID
	Kind   string
	Amount string
}

func (q *Queries) UnrecordedCardSales(ctx context.Context, arg UnrecordedCardSalesParams) ([]UnrecordedCardSalesRow, error) {
	rows, err := q.db.Query(ctx, unrecordedCardSales, arg.StoreID, arg.Day)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UnrecordedCardSalesRow
	for rows.Next() {
		var i UnrecordedCardSalesRow
		if err := rows.Scan(&i.ID, &i.Kind, &i.Amount); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

