const voidCardSplit = `-- name: VoidCardSplit :one
SELECT COALESCE(sum(-l.principal_delta),0)::text AS principal,
       COALESCE(sum(-l.bonus_delta),0)::text AS bonus
FROM order_voids v
JOIN order_payments p ON p.tenant_id=v.tenant_id AND p.order_id=v.order_id
JOIN card_ledger l ON l.tenant_id=p.tenant_id AND l.id=p.card_ledger_id
WHERE v.store_id=$1 AND v.business_date=$2 AND p.method='card'
`

type VoidCardSplitParams struct {
	StoreID uuid.UUID
	Day     pgtype.Date
}

type VoidCardSplitRow struct {
	Principal string
	Bonus     string
}

func (q *Queries) VoidCardSplit(ctx context.Context, arg VoidCardSplitParams) (VoidCardSplitRow, error) {
	row := q.db.QueryRow(ctx, voidCardSplit, arg.StoreID, arg.Day)
	var i VoidCardSplitRow
	err := row.Scan(&i.Principal, &i.Bonus)
	return i, err
}

